import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { UI_PARTS, type UiPartSpec } from "@capybara-hq/plugin-sdk";
import type { Finding } from "./source.js";

export type { Finding };

/** Where the generated files live, relative to the repository root. */
export const DESIGN_PARTS_TS = "packages/design/src/ui-parts.generated.ts";
export const PLUGIN_CLIENT_PARTS_TS = "packages/plugin-client/src/ui-parts.generated.ts";
export const UI_PARTS_DOC = "docs/guide/ui-parts.md";

const HEADER = "// Generated by pnpm gen:ui-parts from @capybara-hq/plugin-sdk; do not edit.";

/** `<head>[…]<tail>`, one item per line (biome's layout) when it does not fit in 100 columns. */
function declareList(head: string, values: readonly string[], tail: string): string {
  const items = values.map((v) => JSON.stringify(v));
  const one = `${head}[${items.join(", ")}]${tail}`;
  if (one.length <= 100) return one;
  return [`${head}[`, ...items.map((i) => `  ${i},`), `]${tail}`].join("\n");
}

function renderNames(parts: readonly UiPartSpec[], docLine: string): string {
  const names = parts.map((p) => p.name);
  return [
    HEADER,
    "",
    `export type UiPartName =\n  | ${names.map((n) => JSON.stringify(n)).join("\n  | ")};`,
    "",
    docLine,
    declareList("export const UI_PART_NAMES: readonly UiPartName[] = ", names, ";"),
    "",
  ].join("\n");
}

/** The generated design-package copy of the part names (design imports no SDK). */
export function renderDesignUiPartsTs(parts: readonly UiPartSpec[]): string {
  return renderNames(parts, "/** Every `data-cap-part` name the design system may render. */");
}

/** The generated `@capybara-hq/plugin-client` copy of the part names. */
export function renderPluginClientUiPartsTs(parts: readonly UiPartSpec[]): string {
  return renderNames(parts, "/** Every part name plugin CSS and components may rely on. */");
}

const code = (values: readonly string[]) =>
  values.length === 0 ? "none" : values.map((v) => `\`${v}\``).join(", ");

/** The generated docs page: a table of every part and a section per part. */
export function renderUiPartsDoc(parts: readonly UiPartSpec[]): string {
  const rows = parts.map(
    (p) => `| \`${p.name}\` | ${p.version} | ${code(p.states)} | ${p.description.en} |`,
  );
  const sections = parts.map((p) =>
    [
      `## \`${p.name}\``,
      "",
      p.description.en,
      "",
      `- Version: ${p.version}`,
      `- States: ${code(p.states)}`,
      `- Owner: \`${p.owner}\``,
      `- Selector: \`[data-cap-part~="${p.name}"]\``,
      "",
    ].join("\n"),
  );
  return [
    "<!-- Generated by pnpm gen:ui-parts from @capybara-hq/plugin-sdk; do not edit. -->",
    "",
    "# UI parts",
    "",
    "The built-in elements plugin CSS may select. Each carries a literal `data-cap-part` attribute,",
    'which may hold several names; select with `[data-cap-part~="<name>"]`.',
    "",
    "| Part | Version | States | Element |",
    "|---|---|---|---|",
    ...rows,
    "",
    ...sections,
  ].join("\n");
}

function staleFindings(root: string, parts: readonly UiPartSpec[]): Finding[] {
  const out: Finding[] = [];
  for (const [rel, expected] of [
    [DESIGN_PARTS_TS, renderDesignUiPartsTs(parts)],
    [PLUGIN_CLIENT_PARTS_TS, renderPluginClientUiPartsTs(parts)],
    [UI_PARTS_DOC, renderUiPartsDoc(parts)],
  ] as const) {
    const file = join(root, rel);
    const actual = existsSync(file) ? readFileSync(file, "utf8") : undefined;
    if (actual === expected) continue;
    const a = (actual ?? "").split("\n");
    const e = expected.split("\n");
    let line = 0;
    while (line < e.length && a[line] === e[line]) line++;
    out.push({
      file,
      line: line + 1,
      rule: "ui-parts-stale",
      message:
        actual === undefined
          ? `${rel} is missing; run pnpm gen:ui-parts`
          : `${rel} differs from the SDK part catalog; run pnpm gen:ui-parts (never edit it by hand)`,
    });
  }
  return out;
}

/**
 * check:ui-parts. This task: the generated copies and the docs page equal what gen:ui-parts renders
 * from the SDK catalog (`ui-parts-stale`). The render rules arrive with the data-cap-part attributes.
 */
export function checkUiParts(root: string, parts: readonly UiPartSpec[] = UI_PARTS): Finding[] {
  return staleFindings(root, parts);
}
